entries[43578] = { ["name"] = "Kampfrausch", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht 10 Sek. lang das Angriffstempo eines Verbündeten um 100%." }
entries[43579] = { ["name"] = "Giftspucke", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nSpuckt Gift auf den Feind, fügt ihm 7000 to 9000 Naturschaden und dann 5 Sek. lang alle 1 Sek. zusätzliche 4625 to 5375 Schaden zu." }
entries[43580] = { ["name"] = "Tödliches Gift", ["text"] = "(Procchance: 25%)" }
entries[43581] = { ["name"] = "Tödliches Gift", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt einem Gegner 12 Sek. lang alle 3 Sek. 500 Naturschaden zu." }
entries[43582] = { ["name"] = "Flammenatem", ["text"] = "Nahkampfreichweite\nSofort\nFügt Feinden in einem kegelförmigen Bereich vor dem Zaubernden 3000 Feuerschaden zu." }
